use std::collections::HashMap;

fn lookup_domain<'a>(map: &'a HashMap<String, String>, key: &str) -> Option<⟦ret_ty⟧> {
    map.get(key)⟦transform⟧
}

fn main() {
    let mut map = HashMap::new();
    map.insert(String::from("app"), String::from("example.com"));
    let res: Option<&str> = lookup_domain(&map, "app");
    println!("{:?}", res);
}

tests:
#[test]
fn test_lookup() {
    let mut map = HashMap::new();
    map.insert(String::from("app"), String::from("example.com"));
    let res: Option<&str> = lookup_domain(&map, "app");
    assert_eq!(res, Some("example.com"));
    assert_eq!(lookup_domain(&map, "missing"), None);
}
